        self.messages = container.decodeLenient([MoodleLessonFinishAttemptResponseMessage].self, forKey: .messages) ?? []
        self.warnings = container.decodeLenient([MoodleWarning].self, forKey: .warnings) ?? []
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(messages, forKey: .messages)
        try container.encode(warnings, forKey: .warnings)
    }
}

public struct MoodleLessonProcessPageResponse: Codable, Hashable, Sendable {
    /// New page id (if a jump was made).
    public var newpageid: Int
    /// Whether the page processing redirect directly to anoter page.
    public var inmediatejump: Bool
    /// Whether there is not a default response.
    public var nodefaultresponse: Bool
    /// The response feedback.
