        self.progress = container.decodeLenient(Int.self, forKey: .progress) ?? 0
        self.displaymenu = container.decodeLenient(Bool.self, forKey: .displaymenu) ?? false
        self.messages = container.decodeLenient([MoodleLessonFinishAttemptResponseMessage].self, forKey: .messages) ?? []
